DAMICParticleSource::DAMICParticleSource(){
    _particleEnergy=0.0 * keV;
    _particleCharge=0.0;
    _particleMomentumDirection=G4ParticleMomentum(1.,0.,0.);
    _particleTime=0.0;
    _particleDefinition=NULL;
    _particlePosition=G4ThreeVector(0.,0.,0.0);

    //Position
    _bSurface = false; //True on surface
    _bVolume = false; //True if Volume
    _bMaterial = false;
    _bShape = false;
    _bSource = true;
    _bList = false;
    
    _volumeSource = "Volume"; // choose between Volume and Material
    _materialSource = "MaterialSource";
    _motherVolume = "MotherWorld";
    _material = "Material";
    _shape = "Para";
    _volumesUse = {};
    _volumesUseMass = {};
    _volumesConcentration = {};
    _proba = {};
    _positionNum = {};
    _energyNum = {};
    _energyProba = {};
    _directionNum = {};
    _bchanges = false;

    //Energy
    _distriNRJ = "Uniform";
    _bMonoNRJ = true;
    _bDistriNRJ = false;
    _histoNRJ = "";

    // Direction
    _distriD = "Isotropic";
    _bDistriD = false;
    _bOneD = true;

    // Tritium
    _bcalculatedMaxTri = false;
    _maxTritium = 0;

    //cosmogenic - shielding
    _CosmoPart = "muon";
    _CosmoAngDistType = "iso";
    _CosmoShapeType = "cuboid"; 
    _CosmoMinTheta = 0.;
    _CosmoMaxTheta = pi;
    _CosmoMinPhi = 0.;
    _CosmoMaxPhi = twopi;
    
    _bCosmogenic = false;
    _bInputFile = false ; 
    //_CosmoCentreCoords = zero;
    // _CosmoSourceCubeSizes = zero;

    //Navigator for Geometry
    _gNavigator = G4TransportationManager::GetTransportationManager()->GetNavigatorForTracking();

    //Messenger
    _messenger = new DAMICParticleSourceMessenger(this);
    _coordinateStore = new DAMICVolumeCoordinateStore(G4PhysicalVolumeStore::GetInstance());

    treein=NULL;
}

DAMICParticleSource::~DAMICParticleSource()
{
    delete _messenger;
    delete _coordinateStore;
    delete treein;
    fin->Close();
}

void DAMICParticleSource::SetReadingShieldFile(G4bool val) {
   _bInputFile = val;
}

void DAMICParticleSource::ReadParticleFile(G4String val) {

  fin = new TFile(val.c_str(),"io::read");

  if (fin->IsOpen())
    G4cout << G4endl <<  " ******** Reading file: " << val << G4endl << G4endl;
  
  if (! fin->IsOpen())
    G4cout << G4endl <<  " ********  ERROR reading file " << val << G4endl << G4endl; 

  if (! fin->GetListOfKeys()->Contains("ShieldOut"))
    G4cout << G4endl <<  " ********  ERROR reading file " << val << " TTree Shield Out not fond! " << G4endl << G4endl;
  SetReadingShieldFile(true);
  
  treein = (TTree*)fin->Get("ShieldOut");
  
  treein->SetBranchAddress("EventID", &in_EventID);
  treein->SetBranchAddress("pdg",&in_pdg);
  treein->SetBranchAddress("trackid",&in_trackid);
  treein->SetBranchAddress("energy",&in_energy);
  treein->SetBranchAddress("time",&in_time);
  treein->SetBranchAddress("posx",&in_posx);
  treein->SetBranchAddress("posy",&in_posy);
  treein->SetBranchAddress("posz",&in_posz);
  treein->SetBranchAddress("momx",&in_momx);
  treein->SetBranchAddress("momy",&in_momy);
  treein->SetBranchAddress("momz",&in_momz);  
  treein->SetBranchAddress("weight",&in_weight); 
  treein->SetBranchAddress("layerID",&in_layerID);    
   G4cout << G4endl <<  " ******** Entries = " << treein->GetEntries() << G4endl;
} 

  


