void DAMICParticleSource::GenerateMuonEnergyDist()
{
  //4.2 LSM, 6.01sno
  G4double h = 4.2;//6.01; //_LabDepth/1.e6; //h converted by G4 in mm 
  G4double rndm = 2.;
  G4double y_rndm = 2.;
  G4double emin = 0.01; //in GeV
  G4double emax = 5000; //in GeV
  G4double A = 1;


  G4double b = 0.438*h;
  G4double g_mu = 3.77;
  G4double eps_mu = 495;
  G4double p = 1.;
  A = 1./(exp(-b*(g_mu-1)) * pow(eps_mu*(1 - exp(-b)), -g_mu)); // value at 0;

  G4int nsteps = 0;
  
  if (h==0) { G4cout << " still something wrong with h" << G4endl; return;}
  rndm = G4UniformRand()*(emax - emin) + emin;
  y_rndm = G4UniformRand();
  p = A*exp(-b*(g_mu-1)) * pow(rndm + eps_mu*(1 - exp(-b)), -g_mu);

   while (y_rndm > p) {
    if (p>1) 
      G4cout << "WARMIMG : PLEASE CHECK MU GEN p > 1 "<< p  << " for " << A << "* exp(-" << b <<"*("<<g_mu-1<<")) * pow("<<rndm << " + " << eps_mu*(1-exp(-b)) << ", " << -g_mu << G4endl;

    rndm = G4UniformRand()*(emax - emin) + emin;
    y_rndm = G4UniformRand();
    p = A*exp(-b*(g_mu-1)) * pow(rndm + eps_mu*(1 - exp(-b)), -g_mu);
  }
  
  emin = emin*GeV;
  emax = emax*GeV; 
  _particleEnergy=rndm*GeV; 
 
  
}

void DAMICParticleSource::GenerateMax()
{
	G4double maxE = 1*eV;//in eV
	G4double minE = 0*eV;//in eV 
	G4double meanE= 0.026*eV; //in eV

	double p;
	double E;
	double fE;

	double fEmean2 = 2*sqrt((meanE/2.0)/3.14)*pow((1/meanE),3/2)*exp(-(meanE/2)/meanE);

	p = 2;
	fE = 1;

	if (_energyNum[1]>0 && _energyNum[0]>=0 && _energyNum[2]>0){

		maxE = _energyNum[1];
		minE = _energyNum[0];
		meanE = _energyNum[2];
	}

	while(p > fE){

		E = minE + G4UniformRand()*(maxE - minE);
		p = G4UniformRand();
		fE = 2*sqrt(E/3.14)*pow((1.0/meanE),(3/2))*exp(-E/meanE)/fEmean2;
		
	}


	SetParticleEnergy(E);
}

