// ADD VOLUME FOR TON OF VOLUMES ------------------

void DAMICParticleSource::AddVolume(G4String Volume, G4double Concentration)
{
    _coordinateStore->AddVolume(Volume, Concentration);
    G4PhysicalVolumeStore* PVStore = G4PhysicalVolumeStore::GetInstance();
    G4int i = 0;
    G4bool found = false;
    G4double Mass;
    //G4double Dens;
    G4VPhysicalVolume* tempPV;
    while (!found && i<(G4int)PVStore->size())
    {
        tempPV = (*PVStore)[i];
        found  = tempPV->GetName() == Volume;
        if (!found)
        {
            i++;
        }
    }

    if(found == true)
    {
        
	 Mass = tempPV->GetLogicalVolume()->GetMass();
	 G4cout << " simulating volume " << tempPV->GetName() << " with mass[g] " << Mass/CLHEP::g << G4endl;

    }
    else
    {
        G4cout << " **** Error: Volume does not exist **** " << G4endl;
        G4cout << " Ignoring confine condition" << G4endl;
        Mass = 0;
    }

    G4int sizeV= _volumesUse.size();
    G4bool same = false;
    for(G4int j = 0;j<sizeV;j++)
    {
        if(_volumesUse[j]==Volume)
        {
            same = true;
        }
    }

    if (!same)
    {
        _volumesUse.push_back(Volume);
        _volumesUseMass.push_back(Mass);
        _volumesConcentration.push_back(Concentration);
        _bchanges = true;
    }

    _volumesConcentration.push_back(Concentration);
}

void DAMICParticleSource::CalculProba()
{
    if (_bchanges)
    {
        _proba={};
        G4double total = 0;
        G4int sizevols = _volumesUse.size();
        for (G4int i = 0; i <sizevols; i++)
        {
          G4double temp = _volumesConcentration[i]*_volumesUseMass[i];
          total += temp;
          _proba.push_back(temp);
        }

        for (G4int i =0; i <sizevols; i++)
        {
            _proba[i] = _proba[i]/total;
        }
        _bchanges = false;
        for (G4int i =1; i <sizevols;i++)
        {
          _proba[i] += _proba[i-1];
        }
    }
}

void DAMICParticleSource::ChooseVolume()
{
    G4double tryVol = 1*G4UniformRand();
    G4bool found = false;
    G4int i = 0;
    while(!found)
    {
        if (tryVol <= _proba[i])
        {
          found = true;
          _volumeSource = _volumesUse[i];
        }
        i++;
    }
}


