// CalculPositon :: Function that will be called to find a position within a volume that is made of an specific
// material (materialUse), i.e. when domaterial in the macro is used.
// The algorithm randomly generate a position (X,Y,Z) and look if it falls inside a volume of
// material materialUse. In the DAMIC SNOLAB code, there were several defined regions to minimize the
// region to be used to find positions within an specific material.
// FIXME I commented the regions from the DAMIC SNOLAB geometry, and I introduce the minimum one for
// the current geometry. This funcion will be updated as the detector design progresses.
//
void DAMICParticleSource::CalculPosition(G4String /*MotherUse*/,G4String materialUse,G4String volumeUse)
{
  //G4cout << "MotherUse: " << MotherUse << G4endl;
  //G4cout << "materialUse " << materialUse << G4endl;
  //G4cout << "volumeUse: " << volumeUse << G4endl;

      G4double posx = 0;
      G4double posy = 0;
      G4double posz = 0;
      G4bool found = false;
      G4VPhysicalVolume* theVolume;
      G4String theVolName;
      G4String theMaterialName;
      G4bool materialFit;
      G4bool VolumeFit;
      while(!found)
      {
      /*if (MotherUse == "WorldLV" )
      {
        posx = 2.15*m*G4UniformRand()-1.075*m;
        posy = 2.2*m*G4UniformRand()-1.1*m;
        posz = 2.2*m*G4UniformRand()-1.1*m;
      }
        else if (MotherUse == "VesselLV" || MotherUse =="Assembly1"|| MotherUse =="Assembly2")
      {
        posx = 2.0*m*G4UniformRand()-1*m;
        posy = 2.0*m*G4UniformRand()-1*m;
        posz = 2.0*m*G4UniformRand()-1*m;
      }
        else if (MotherUse == "EmptyBox")
      {
        posx = 304.8*mm*G4UniformRand()-304.8/2*mm;
        posy = 304.8*mm*G4UniformRand()-304.8/2*mm;
        posz = 482.6*mm*G4UniformRand()-482.6/2*mm-186.4*mm;
      }
      else if (MotherUse == "PrinTubLV")
      {
        G4double RadiusRan = 191.287/2*mm * G4UniformRand();
        G4double AngleRan = M_PI*2*G4UniformRand();
        G4double HeightRan = 413.512*mm *(G4UniformRand()-0.5);
        posx = RadiusRan* cos(AngleRan);
        posy = RadiusRan* sin(AngleRan);
        posz = -120*mm+ HeightRan;
      }
      else if (MotherUse == "CCDStackModule")
      {assuming x,y and z between -200 and 200, -200 and 200, -300 and 300, respectively
      */
          posx = 200.0*mm*((2*G4UniformRand()-1.0)/2.);
          posy = 200.0*mm*((2*G4UniformRand()-1.0)/2.);
          posz = 300.0*mm*((2*G4UniformRand()-1.0)/2.);

      // FIXME find a way to figure out the maximum size of the volume!!
      /*}
      else
      {
        posx = 2*m*(G4UniformRand()-0.5);
        posy = 2*m*(G4UniformRand()-0.5);
        posz = 2*m*(G4UniformRand()-0.5);
      }*/

        G4ThreeVector *ptr = nullptr;
        theVolume=_gNavigator->LocateGlobalPointAndSetup(G4ThreeVector(posx,posy, posz),ptr,true);
        theVolName = theVolume->GetName();
        theMaterialName = theVolume->GetLogicalVolume()->GetMaterial()->GetName();
        materialFit = theMaterialName == materialUse;
        VolumeFit = theVolName == volumeUse;
        if (materialFit && IsMaterial())
        {
            found = true;
        }
        if (VolumeFit && IsVolume())
        {
            found = true;
        }
      }
      SetParticlePosition(G4ThreeVector(posx, posy, posz));
}


// SHAPE COORDINATES ------------------

void DAMICParticleSource::ShapeCoordinates()
{
  G4double X;
  G4double Y;
  G4double Z;
  if (_shape == "Para")
  {
    G4ThreeVector Center = G4ThreeVector(_positionNum[0], _positionNum[1], _positionNum[2]);
    G4ThreeVector Sides = G4ThreeVector(_positionNum[3], _positionNum[4], _positionNum[5]);
    X = Center.getX()+ Sides.getX()*(G4UniformRand()-0.5);
    Y = Center.getY()+ Sides.getY()*(G4UniformRand()-0.5);
    Z = Center.getZ()+ Sides.getZ()*(G4UniformRand()-0.5);
  }
  else if (_shape == "Sphere")
  {
    G4ThreeVector Center = G4ThreeVector(_positionNum[0], _positionNum[1], _positionNum[2]);
    G4double Radius = _positionNum[3];
    G4double cosTeta = 2*(G4UniformRand()-0.5);
    G4double sinTeta = sqrt(1-cosTeta*cosTeta);
    G4double AnglePhi = M_PI*2*G4UniformRand();
    G4double Rad = Radius*G4UniformRand();
    X = Rad*sin(AnglePhi)*cosTeta+ Center.getX();
    Y = Rad*sin(AnglePhi)*sinTeta+ Center.getY();
    Z = Rad*cos(AnglePhi)+ Center.getZ();

  }
  else if (_shape == "Cyl")
  {
    G4ThreeVector Center = G4ThreeVector(_positionNum[0], _positionNum[1], _positionNum[2]);
    G4double Radius = _positionNum[3];
    G4double Height = _positionNum[4];
    G4double Rad = Radius*G4UniformRand();
    G4double AngleTeta = M_PI*2*G4UniformRand();
    X = Center.getX() + Rad*cos(AngleTeta);
    Y = Center.getY()+ Rad * sin(AngleTeta);
    Z =Center.getZ() + Height *(G4UniformRand()-0.5);
  }
  else
  {
    G4cout << " *****This _shape is not defined***** " << G4endl;
    X = 0;
    Y = 0;
    Z = 0;
  }
  SetParticlePosition(G4ThreeVector(X,Y,Z));
}

// RANDOM VECTOR INITIALIZATION

void DAMICParticleSource::RandomVecProf(std::vector<G4double>* vec)
{
  int size = vec->size();
  for(int i = 1; i< size; i++)
  {
    vec->at(i) += vec->at(i-1);
  }
  for (int i =0; i < size; i++)
  {
    vec->at(i) = vec->at(i)/vec->at(size-1);
   
  }
}

// Pick ID Random
G4int DAMICParticleSource::PickRandom(std::vector<G4double>* vec)
{

  int size = vec->size();
  G4double prob = G4UniformRand();
  G4int i =0;
  for(; i < size; i++)
  {
    if ( prob < vec->at(i))
    {
      return i;
    }
  }
  return -1;
}

// ENERGY VALUES

void DAMICParticleSource::ReadHistoNRJ()
{
  std::ifstream file(_histoNRJ, std::ios::in);
  if(file)
  {
    while(!file.eof())
    {
      double nrj;
      double prob;
      file >> nrj >> prob;
      _energyNum.push_back(nrj*keV);
      _energyProba.push_back(prob);
    }
    file.close();
  }
  else
  {
    G4cout << "File doesn't exist" << G4endl;  // shouldn't happen cause checked before
  }
}


void DAMICParticleSource::EnergyValue()
{
  
  if (IsCosmogenic()) {
    if (_CosmoPart == "Muon" || _CosmoPart == "muon")
      GenerateMuonEnergyDist();
    else //add here neutron energy dist
      G4cout << "Error: EnergyDisType has unusual value" << G4endl; //FIX THIS !!! Should be allowed not to give any energy dist
  }
  

  if (IsMonoNRJ())
  {
    SetParticleEnergy(_energyNum[0]);
  }

  if (IsDistriNRJ())
  {

    G4double EnergyRand = 0;
    if (_distriNRJ == "Uniform")
    {
      EnergyRand = G4UniformRand() * (_energyNum[1]-_energyNum[0]) + _energyNum[0];
    }
    if (_distriNRJ == "Tritium")
    {
      G4double endpoint = 18580;
      if (!_bcalculatedMaxTri)
      {
        G4double max = 0;

        for (int i = 0; i < endpoint; i+=10)
        {
          G4double tempMax = SpectrumBeta(i);
          if (tempMax > max)
          {
            max = tempMax;
          }
        }
        _bcalculatedMaxTri = true;
        _maxTritium = max;
      }

      G4bool doneFind = false;
      while (!doneFind)
      {
        G4double tempRand1 = G4UniformRand() * (endpoint-1) +1;
        G4double relation = SpectrumBeta(tempRand1)/_maxTritium;
        G4double tempRand2 = G4UniformRand();
        if ( tempRand2 < relation)
        {
          doneFind = true;
        }
        EnergyRand = tempRand1*eV; //FIX IT ! use same energy units everywhere
      }
    }
    if(_distriNRJ == "Histo")
    {
      if(_energyProba.size() ==0)
      {
        ReadHistoNRJ();
        RandomVecProf(&_energyProba);
      }
      G4int IDnrj = -1;
      G4int tests = 0;
      while(IDnrj == -1 && tests <= 30)
      {
        IDnrj = PickRandom(&_energyProba);
        tests++;
      }
      if( tests == 30)
      {
        G4cout << " Making a 1 keV nrj" << G4endl;
        EnergyRand = 1*keV;
      }
      else
      {
        EnergyRand = _energyNum[IDnrj];
      }
    }

    SetParticleEnergy(EnergyRand);

    if(_distriNRJ == "Max")
    {
      GenerateMax();
    }

    if (_distriNRJ == "Neutron_UTh_Rock" || _distriNRJ == "Neutron_Cosmo_Rock" || _distriNRJ == "Neutron_Lead"){
      GenerateNeutronEnergyDist();
    }

  }

}

G4double DAMICParticleSource::SpectrumBeta(G4double En)
{
  G4double Q = 18580;
  G4double E = En;
  G4double elecMass = 511000;
  G4double FirstPart = sqrt(E*E+2*E*elecMass);
  G4double SecondPart = (Q-E)*(Q-E)*(E+elecMass);

  G4double Z = 1;
  G4double alpha = 7.2973525664 * 0.001;
  G4double nu = 2*alpha*Z*(E+elecMass)/(FirstPart);

  G4double FermiFunction = 2*3.14*nu/(1-exp(-2*3.14*nu));

  G4double result = FirstPart*SecondPart*FermiFunction;

  return result;
}

// DIRECTION VALUE

void DAMICParticleSource::DirectionValue()
{
  if (IsOneD())
  {
    SetParticleMomentumDirection(G4ParticleMomentum(_directionNum[0],_directionNum[1],_directionNum[2]));
  }
  if (IsDistriD())
  {
    if (_distriD == "Isotropic")
    {
      G4double thetaMin = _directionNum[0];
      G4double thetaMax = _directionNum[1];
      G4double phiMin = _directionNum[2];
      G4double phiMax = _directionNum[3];

      G4double cosTheta = cos(thetaMin) - G4UniformRand()*(cos(thetaMin)-cos(thetaMax));
      G4double sinTheta = sqrt(1-cosTheta*cosTheta);

      G4double Phi = phiMin + (phiMax - phiMin) * G4UniformRand();
      G4double cosPhi = cos(Phi);
      G4double sinPhi = sin(Phi);

      G4double px = -sinTheta * cosPhi;
      G4double py = -sinTheta * sinPhi;
      G4double pz = -cosTheta;

      G4double ResMag = sqrt((px*px)+ (py*py)+(pz*pz));
      px = px/ResMag;
      py = py/ResMag;
      pz = pz/ResMag;

      SetParticleMomentumDirection(G4ParticleMomentum(px, py, pz));
    }
  }
}


//MAIN-----------------

void DAMICParticleSource::GeneratePrimaryVertex(G4Event* evt)
{
  
  /* if (IsCosmogenic() && IsReadingShieldFile()) {
    G4cout << G4endl << "  something wrong in your macro: Cosmogenic and Reading file options are not compatible" << G4endl;
    return;
  }
  else */ 
	if (_bInputFile )  {

		G4double mass = 0;
		G4double Energy = 0;
  
		_particlePosition[0] = 0;
		_particlePosition[1] = 0;
		_particlePosition[2] = 0;
		_particleDefinition = G4ParticleTable::GetParticleTable()->FindParticle("geantino");

		_particleMomentumDirection[0] = 0; 
		_particleMomentumDirection[1] = 0;
		_particleMomentumDirection[2] = 0;
     
		_particleTime = 0; 
		_particleEnergy = 0;

		G4double px = 0;
		G4double py = 0;
		G4double pz = 0;
		G4int nall = 0;
  
		int id = evt->GetEventID(); 
      
		if (id>=treein->GetEntries()) {
			G4cout << " ERROR: evt ID > total number of entries in the input file " << G4endl;
			return;
		}
		else {    
			treein->GetEntry(id);
			nall = (int)in_posx->size();
		}
      
		if (nall==0) {
			G4PrimaryParticle* particle = new G4PrimaryParticle(_particleDefinition, px, py, pz);
			particle->SetMass( 0 );
			particle->SetCharge( 0 );

			G4PrimaryVertex* vertex = new G4PrimaryVertex(_particlePosition, _particleTime);
			vertex->SetPrimary( particle );
			evt->AddPrimaryVertex(vertex);
	  
			return;
		}
		else{
			for (int k = 0; k <nall; k++) {
				_particleEnergy = in_energy->at(k)*CLHEP::eV;
				_particleDefinition = G4ParticleTable::GetParticleTable()->FindParticle(in_pdg->at(k));
				mass = _particleDefinition->GetPDGMass();
				Energy = _particleEnergy + mass;

				_particlePosition[0] = in_posx->at(k);
				_particlePosition[1] = in_posy->at(k);
				_particlePosition[2] = in_posz->at(k);

				px = in_momx->at(k);//pmom*_particleMomentumDirection.x();
				py = in_momy->at(k);//pmom*_particleMomentumDirection.y();
				pz = in_momz->at(k);//pmom*_particleMomentumDirection.z();
	
				G4double pmom = std::sqrt(Energy*Energy-mass*mass);
	
				_particleMomentumDirection[0] = px/pmom;
				_particleMomentumDirection[1] = py/pmom;
				_particleMomentumDirection[2] = pz/pmom;																				  
				_particleTime = in_time->at(k)*CLHEP::s;																									    
				G4PrimaryVertex* vertex = new G4PrimaryVertex(_particlePosition, _particleTime);
       
				G4PrimaryParticle* particle = new G4PrimaryParticle(_particleDefinition, px, py, pz);
 				particle->SetMass( mass );
				particle->SetCharge( _particleCharge );
				//particle->Set4Momentum( px, py, pz, Energy);
				vertex->SetPrimary( particle );
				evt->AddPrimaryVertex(vertex);
			} //end for k
		}

	}// end if input_file 
	else  if (IsCosmogenic() ) {
		ShapeCoordinates();
		if (_CosmoPart == "Muon" || _CosmoPart == "muon") GenerateMuonEnergyDist();
		if (_CosmoPart == "neutron") GenerateNeutronEnergyDist();

		if (_CosmoAngDistType == "Muon" || _CosmoAngDistType == "muon" || _CosmoAngDistType == "cosmo") {
			GenerateMuonAngleDist();
		}
		else if (_CosmoAngDistType == "iso") GenerateIsotropicFlux();
		else if (_CosmoAngDistType == "direction"){
			SetParticleMomentumDirection(G4ParticleMomentum(_directionNum[0],_directionNum[1],_directionNum[2]));
		}
		else { 
			G4cout << " angular distribution for cosmogenic primaries not defined" << G4endl;
			return;
		}
      
		_particleTime = 0.0;
        
		G4PrimaryVertex* vertex = new G4PrimaryVertex(_particlePosition, _particleTime);
		G4double mass = _particleDefinition->GetPDGMass();
		G4double Energy = _particleEnergy + mass;
		G4double pmom = std::sqrt(Energy*Energy-mass*mass);
		G4double px = pmom*_particleMomentumDirection.x();
		G4double py = pmom*_particleMomentumDirection.y();
		G4double pz = pmom*_particleMomentumDirection.z();
    
		G4PrimaryParticle* particle = new G4PrimaryParticle(_particleDefinition, px, py, pz);
		particle->SetMass( mass );
		particle->SetCharge( _particleCharge );
		vertex->SetPrimary( particle );
		evt->AddPrimaryVertex(vertex);
	} //end if cosmogenic
	else  {
		if(_particleDefinition == NULL ) {
        	G4cout << "No particle has been defined!" << G4endl;
        	return;
		} 
		if (IsMaterial())
		{
		    MaterialCoordinates();
		}
		if (IsVolume())
		{
		    CalculProba();
		    ChooseVolume();
		    VolumeCoordinates();
		}

		if (IsSource())
		{
		    SourceCoordinates();
		}
    
		if (IsShape())
		{
		    ShapeCoordinates();
		}
    
		if (IsSurface())
		{
		    SurfaceCoordinates();
		}
    
		if (IsList())
		{
		    ListCoordinates();
		}

  
		// DIRECTION
		DirectionValue();

		//ENERGY
		EnergyValue();
		
		G4PrimaryVertex* vertex = new G4PrimaryVertex(_particlePosition, _particleTime);
		G4double mass = _particleDefinition->GetPDGMass();
		G4double Energy = _particleEnergy + mass;
		G4double pmom = std::sqrt(Energy*Energy-mass*mass);
		G4double px = pmom*_particleMomentumDirection.x();
		G4double py = pmom*_particleMomentumDirection.y();
		G4double pz = pmom*_particleMomentumDirection.z();
		G4PrimaryParticle* particle = new G4PrimaryParticle(_particleDefinition, px, py, pz);
		particle->SetMass( mass );
		particle->SetCharge( _particleCharge );
		vertex->SetPrimary( particle );
		evt->AddPrimaryVertex(vertex);
    } //end else 
  
}
